const {seg,eo,eio,lerp}=kit;
kit.scene('hook',{
 init(kit){
  this.root=W.mount(kit,'hook');
  this.root.append(kit.h('<div class="words hook-title" style="left:112px;top:286px;width:1090px;gap:8px"><h1 style="font-size:142px;font-weight:650;line-height:1.22;letter-spacing:-5px">多个 Agent，</h1><h2 style="font-size:142px;font-weight:650;line-height:1.25;letter-spacing:-5px">各做各的任务。</h2><p class="hook-detail muted" style="font-size:37px;line-height:1.6;margin-top:42px">不同 Profile／应用，分别管理。</p></div>'));
  const svg='<svg class="hook-routes" viewBox="0 0 1920 1080" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none"><g style="fill:none;stroke:color-mix(in srgb,var(--main) 18%,var(--ground));stroke-width:4"><path d="M1210 565 Q1440 565 1550 335 H1720"/><path d="M1210 565 H1720"/><path d="M1210 565 Q1440 565 1550 795 H1720"/></g><g class="hook-hub"><rect x="1166" y="521" width="88" height="88" rx="20" style="fill:var(--main)"/><path d="M1194 553 L1206 565 L1194 577 M1220 553 L1232 565 L1220 577" style="fill:none;stroke:var(--ground);stroke-width:5;stroke-linecap:round;stroke-linejoin:round"/></g><g style="fill:var(--main)"><circle class="hook-dot" r="9"/><circle class="hook-dot" r="9"/><circle class="hook-dot" r="9"/></g><g class="hook-targets" style="fill:var(--ground);stroke:var(--main);stroke-width:3"><rect x="1660" y="285" width="128" height="100" rx="10"/><path d="M1660 312 H1788 M1674 299 H1702"/><rect x="1660" y="515" width="128" height="100" rx="10"/><path d="M1660 542 H1788 M1674 529 H1702"/><rect x="1660" y="745" width="128" height="100" rx="10"/><path d="M1660 772 H1788 M1674 759 H1702"/></g></svg>';
  this.root.append(kit.h(svg));
  this.root.append(kit.h('<div class="hook-labels"><div class="words" style="left:1530px;top:402px;width:280px;align-items:flex-end"><p class="small">资料 Profile</p></div><div class="words" style="left:1530px;top:632px;width:280px;align-items:flex-end"><p class="small">测试 Profile</p></div><div class="words" style="left:1530px;top:862px;width:280px;align-items:flex-end"><p class="small">独立应用</p></div></div>'));
  this.title=this.root.querySelector('.hook-title');this.detail=this.root.querySelector('.hook-detail');this.paths=this.root.querySelector('.hook-routes');this.dots=[...this.root.querySelectorAll('.hook-dot')];this.labels=this.root.querySelector('.hook-labels');
 },
 render(t){
  this.title.style.transform='translateY('+lerp(0,-7,eio(seg(t,0,4)))+'px)';
  W.reveal(this.detail,t,.35,18,.65);
  const intro=eo(seg(t,-.8,.3));this.paths.style.opacity=intro;this.labels.style.opacity=intro;
  const ys=[335,565,795];
  this.dots.forEach((d,i)=>{const p=((Math.max(0,t)+i*.55)%2.4)/2.4;const xy=i===1?[lerp(1210,1720,p),565]:p<.76?W.pathPoint(p/.76,1210,565,1440,565,1550,ys[i]):[lerp(1550,1720,(p-.76)/.24),ys[i]];W.dot(null,d,...xy);d.style.opacity=.3+.7*Math.sin(Math.PI*p);});
  W.progress(this.root,t,0);
 }
});
